answers={str(k):int(v) for k,v in prof['answers'].items()}
# co-occurrence map: for each charge, the multiset of other charges it is written with
from collections import Counter, defaultdict
co=defaultdict(Counter)
for text,count in answers.items():
    units=split_items(text)
    if len(units)<2: continue
    for u in units:
        for v in units:
            if v!=u: co[u][v]+=count
runs = {'ea3b299':'9f49dd7221d29df0c6f8b80f8f04a8b2b2b607f7','d7b155f':'bca9cc83e78c40aec26b992045b54b53d51b049b','3340e63':'e2c96b80fe6f6045ce76e249acfdb3eaab900dfd','7628d2a':'8b90b9c533d81d047bcfa360458b9b5b1f664fb9','e5d4cc5':'3c5c61e1a2505a79fcd73b63596601425207a4bb','d8f5ef0':'37a3ebb74a30bacfa2ab2379c86fa408af47a2fd','3bb9672':'cd1bd0d40a39e7f9807fa0f12a58902c73abec2d','5402cb1':'b000c8efdc1973bb7b24cd9430e5f9a612f2bf24','a311512':'4383c6264deaf3410877e957b8f891f1f3da2936','cadc26b':'ceeb3c6c371878d0818744024906d9acd941dc6a','bc19c51':'84fb7ecd4aa0f4a1ab2a71b3fec90e281f407964','f071ba2':'8ccc11393d600b9e48147fab5c3c03829576e8fc'}
def txt(msg):
    c=msg.get('content')
    if isinstance(c,list): return ''.join(p.get('text','') if isinstance(p,dict) else str(p) for p in c)
    return c or ''
def answer_of(text):
    m=re.search(r'"final_answer"\s*:\s*"((?:[^"\\]|\\.)*)"', text, re.S)
    if m:
        try: return json.loads('"'+m.group(1)+'"')
        except Exception: return m.group(1)
    return text
from collections import Counter as C2
stats=C2(); ex=[]
for name,t in runs.items():
    for f in sorted(glob.glob(f'/workspace/runs/{t}/LawBench/conversations/0*/sample-*.json')):
        d=json.load(open(f))
        if d['status']!='ok': continue
        asst=[txt(m) for m in d['messages'] if m.get('role')=='assistant']
        asst=[a for a in asst if a.strip()]
        if not asst: continue
        ctx="".join(txt(m) for m in d['messages'] if m.get('role')=='tool')
        P=answer_of(asst[0]); items=set(answer_items(P)); T=set(split_items(d['target']))
        correct = items==T
        has_notice = bool(answer_notice(prof,P,ctx))
        miss=T-items
        fired=False; pointed=[]
        for W in items:
            if W in T and co.get(W):
                for M in miss:
                    if co[W].get(M):
                        fired=True; pointed.append((W,M))
        if correct:
            stats['correct_rule_fires' if fired else 'correct_rule_silent']+=1
        else:
            if fired: stats['wrong_rule_fires']+=1
            else: stats['wrong_rule_silent']+=1
            if fired and not has_notice and len(ex)<10: ex.append((name,d['example_index'],d['sample_index'],sorted(items),sorted(T),pointed[:3]))
print(dict(stats))
for e in ex: print(e)
